  use Veltrion\Services\AI\FeatureEngine\DTOs\FeatureDTO; use Veltrion\Services\AI\FeatureEngine\DTOs\RequirementDTO; use Veltrion\Services\AI\FeatureEngine\Enums\FeatureStatus; class FeatureManager { private string $baseDir; public function __construct(?string $baseDir = null) { $this->baseDir = $baseDir ?? __DIR__ . '/../../../../FEATURES'; if (!is_dir($this->baseDir)) { mkdir($this->baseDir, 0777, true); } } public function generateNextId(): string { $year = date('Y'); $maxNum = 0; if (is_dir($this->baseDir)) { $dirs = scandir($this->baseDir); foreach ($dirs as $d) { if (preg_match('/^FEAT-' . $year . '-(\d{4})/', $d, $matches)) { $num = (int)$matches[1]; if ($num > $maxNum) { $maxNum = $num; } } } } $nextNum = str_pad((string)($maxNum + 1), 4, '0', STR_PAD_LEFT); return "FEAT-{$year}-{$nextNum}"; } public function createFeature(string $name, string $description = '', array $requirements = []): FeatureDTO { $id = $this->generateNextId(); $slug = strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/', '-', $name))); $folderName = "{$id}-{$slug}"; $featureDir = "{$this->baseDir}/{$folderName}"; if (!is_dir($featureDir)) { mkdir($featureDir, 0777, true); } $reqObjs = []; $reqCount = 1; foreach ($requirements as $req) { $reqId = "REQ-" . str_pad((string)$reqCount, 4, '0', STR_PAD_LEFT); $reqObjs[] = new RequirementDTO( id: $reqId, description: is_string($req) ? $req : ($req['description'] ?? ''), acceptanceCriteria: is_array($req) ? ($req['acceptance_criteria'] ?? []) : [] ); $reqCount++; } if (empty($reqObjs)) { $reqObjs[] = new RequirementDTO( id: "REQ-0001", description: "Requisito inicial para {$name}", acceptanceCriteria: ["Cumplir con las especificaciones del usuario"] ); } $feature = new FeatureDTO( id: $id, name: $name, slug: $slug, status: FeatureStatus::PLANNED, description: $description ?: "Implementación de {$name}", requirements: $reqObjs ); $this->saveFeatureFiles($featureDir, $feature); return $feature; } public function saveFeatureFiles(string $featureDir, FeatureDTO $feature): void { if (!is_dir($featureDir)) { mkdir($featureDir, 0777, true); } $featureMd = "# Feature: {$feature->name} ({$feature->id})\n\n" . "**ID**: `{$feature->id}`\n" . "**Estado**: `{$feature->status}`\n" . "**Prioridad**: `{$feature->priority}`\n\n" . "## Descripción\n{$feature->description}\n\n" . "## Dependencias\n" . (empty($feature->dependencies) ? "Ninguna\n" : implode("\n", array_map(fn($d) => "- {$d}", $feature->dependencies)) . "\n"); file_put_contents("{$featureDir}/FEATURE.md", $featureMd); $reqMd = "# Requisitos - {$feature->id}\n\n"; foreach ($feature->requirements as $r) { $rArr = is_array($r) ? $r : $r->toArray(); $reqMd .= "## `{$rArr['id']}` - {$rArr['type']}\n"; $reqMd .= "{$rArr['description']}\n\n"; $reqMd .= "**Prioridad**: {$rArr['priority']} | **Estado**: {$rArr['status']}\n\n"; } file_put_contents("{$featureDir}/REQUIREMENTS.md", $reqMd); $accMd = "# Criterios de Aceptación - {$feature->id}\n\n"; foreach ($feature->requirements as $r) { $rArr = is_array($r) ? $r : $r->toArray(); $accMd .= "### Requisito `{$rArr['id']}`\n"; if (!empty($rArr['acceptance_criteria'])) { foreach ($rArr['acceptance_criteria'] as $ac) { $accMd .= "- [ ] {$ac}\n"; } } else { $accMd .= "- [ ] Criterio de aceptación general verificado\n"; } $accMd .= "\n"; } file_put_contents("{$featureDir}/ACCEPTANCE.md", $accMd); $planMd = "# Plan Técnico - {$feature->id}\n\n" . "## Arquitectura Propuesta\n- Componentes principales Clean Architecture\n\n" . "## Pasos de Ejecución\n1. Crear Migración SQL / Entidad\n2. Crear Repositorio y UseCases\n3. Crear Controlador y Rutas\n4. Ejecutar Suite de Tests y Agentes\n"; file_put_contents("{$featureDir}/PLAN.md", $planMd); $traceMd = "# Matriz de Trazabilidad - {$feature->id}\n\n" . "| Requirement | Code Files | Tests | Security | E2E | Status |\n" . "|---|---|---|---|---|---|\n"; foreach ($feature->requirements as $r) { $rArr = is_array($r) ? $r : $r->toArray(); $traceMd .= "| {$rArr['id']} | Pending | Pending | PENDING | PENDING | {$feature->status} |\n"; } file_put_contents("{$featureDir}/TRACEABILITY.md", $traceMd); } public function findFeature(string $featureIdOrSlug): ?FeatureDTO { $dirs = scandir($this->baseDir); foreach ($dirs as $d) { if ($d === '.' || $d === '..') continue; if (str_contains(strtolower($d), strtolower($featureIdOrSlug))) { $featureDir = "{$this->baseDir}/{$d}"; if (file_exists("{$featureDir}/FEATURE.md")) { return $this->parseFeatureDir($featureDir, $d); } } } return null; } public function listFeatures(?string $statusFilter = null): array { $features = []; if (!is_dir($this->baseDir)) return []; $dirs = scandir($this->baseDir); foreach ($dirs as $d) { if ($d === '.' || $d === '..') continue; $featureDir = "{$this->baseDir}/{$d}"; if (is_dir($featureDir) && file_exists("{$featureDir}/FEATURE.md")) { $feat = $this->parseFeatureDir($featureDir, $d); if ($feat) { if ($statusFilter === null || strtolower($feat->status) === strtolower($statusFilter)) { $features[] = $feat; } } } } return $features; } private function parseFeatureDir(string $featureDir, string $dirName): ?FeatureDTO { $featureMdPath = "{$featureDir}/FEATURE.md"; if (!file_exists($featureMdPath)) return null; $content = file_get_contents($featureMdPath); $id = $dirName; if (preg_match('/^#\s*Feature:\s*(.*?)\s*\((FEAT-[0-9]{4}-[0-9]{4})\)/m', $content, $m)) { $name = $m[1]; $id = $m[2]; } else { $name = $dirName; } $status = FeatureStatus::PLANNED; if (preg_match('/\*\*Estado\*\*:\s*`?([A-Z_]+)`?/i', $content, $m)) { $status = strtoupper($m[1]); } $priority = 'NORMAL'; if (preg_match('/\*\*Prioridad\*\*:\s*`?([A-Z_]+)`?/i', $content, $m)) { $priority = strtoupper($m[1]); } $requirements = []; $reqPath = "{$featureDir}/REQUIREMENTS.md"; if (file_exists($reqPath)) { $reqContent = file_get_contents($reqPath); preg_match_all('/##\s*`(REQ-[0-9]{4})`\s*-\s*([A-Z_]+)\n(.*?)(?=\n##|\z)/s', $reqContent, $matches, PREG_SET_ORDER); foreach ($matches as $m) { $requirements[] = new RequirementDTO( id: $m[1], description: trim($m[3]), type: $m[2] ); } } return new FeatureDTO( id: $id, name: $name, slug: $dirName, status: $status, priority: $priority, description: $content, requirements: $requirements ); } } 